class TimeLimitSchedulerTest {

	@Test
	void deadlineIncludesTimeBeforeRegistrationAndRetainsFractions() {
		AtomicLong clock = new AtomicLong(15_000_000);
		TimeLimitScheduler.Deadline deadline = new TimeLimitScheduler.Deadline(10, 10_000_000, clock::get);

		assertEquals(5, deadline.remainingMillis());
		clock.addAndGet(3_500_000);
		assertEquals(2, deadline.remainingMillis());
		assertEquals(1_500_000, deadline.remainingNanos());
		clock.addAndGet(1_500_000);
		assertEquals(0, deadline.remainingNanos());
		clock.addAndGet(2_000_000);
		assertEquals(-2, deadline.remainingMillis());
	}

	@Test
	void remainingMillisSaturatesInsteadOfWrapping() {
		AtomicLong clock = new AtomicLong();
		TimeLimitScheduler.Deadline minimum = new TimeLimitScheduler.Deadline(Long.MIN_VALUE, 0, clock::get);
		TimeLimitScheduler.Deadline maximum = new TimeLimitScheduler.Deadline(Long.MAX_VALUE, 0, clock::get);

		clock.set(TimeUnit.MILLISECONDS.toNanos(3));
		assertEquals(Long.MIN_VALUE, minimum.remainingMillis());
		assertEquals(0, minimum.remainingNanos());
		assertEquals(Long.MAX_VALUE - 3, maximum.remainingMillis());
		assertEquals(TimeLimitScheduler.MAX_CHECK_INTERVAL_NANOS, maximum.remainingNanos());
	}

	@Test
	void deadlineHandlesNanoTimeCounterWraparound() {
		long start = Long.MAX_VALUE - 499_999;
		AtomicLong clock = new AtomicLong(start);
		TimeLimitScheduler.Deadline deadline = new TimeLimitScheduler.Deadline(2, start, clock::get);

		clock.set(Long.MIN_VALUE + 500_000);
		assertEquals(1, deadline.remainingMillis());
		assertEquals(1_000_000, deadline.remainingNanos());
	}

	@Test
	void largeDelayRearmsAndEarlyWakeDoesNotFire() {
		AtomicLong clock = new AtomicLong();
		long chunk = TimeLimitScheduler.MAX_CHECK_INTERVAL_NANOS;
		long limitMillis = chunk / TimeUnit.MILLISECONDS.toNanos(1) + 2;
		long limitNanos = TimeUnit.MILLISECONDS.toNanos(limitMillis);
		AtomicBoolean fired = new AtomicBoolean();
		try (CapturingExecutor executor = new CapturingExecutor()) {
			TimeLimitScheduler.Task task = new TimeLimitScheduler.Task(() -> fired.set(true), executor, Runnable::run);
			task.schedule(new TimeLimitScheduler.Deadline(limitMillis, 0, clock::get));
			assertEquals(chunk, executor.latest().delayNanos);

			clock.set(chunk);
			executor.latest().run();
			assertEquals(2, executor.tasks.size());
			assertEquals(limitNanos - chunk, executor.latest().delayNanos);
			assertFalse(fired.get());

			clock.set(limitNanos - 1);
			executor.latest().run();
			assertEquals(3, executor.tasks.size());
			assertEquals(1, executor.latest().delayNanos);
			assertFalse(fired.get());

			clock.incrementAndGet();
			executor.latest().run();
			assertTrue(fired.get());
		}
	}

	@Test
	void cancellationBeforeRegistrationAndAfterDispatchPreventsAction() {
		AtomicLong clock = new AtomicLong();
		AtomicBoolean fired = new AtomicBoolean();
		List<Runnable> dispatched = new ArrayList<>();
		try (CapturingExecutor executor = new CapturingExecutor()) {
			TimeLimitScheduler.Task canceledBefore = new TimeLimitScheduler.Task(() -> fired.set(true), executor,
					dispatched::add);
			canceledBefore.cancel();
			canceledBefore.schedule(new TimeLimitScheduler.Deadline(0, 0, clock::get));
			assertTrue(executor.tasks.isEmpty());

			TimeLimitScheduler.Task canceledQueued = new TimeLimitScheduler.Task(() -> fired.set(true), executor,
					dispatched::add);
			canceledQueued.schedule(new TimeLimitScheduler.Deadline(5, 0, clock::get));
			Pending queued = executor.latest();
			canceledQueued.cancel();
			assertTrue(queued.isCancelled());
			queued.run();
			assertTrue(dispatched.isEmpty());

			TimeLimitScheduler.Task canceledAfterDispatch = new TimeLimitScheduler.Task(() -> fired.set(true), executor,
					dispatched::add);
			canceledAfterDispatch.schedule(new TimeLimitScheduler.Deadline(0, 0, clock::get));
			executor.latest().run();
			assertEquals(1, dispatched.size());
			canceledAfterDispatch.cancel();
			canceledAfterDispatch.cancel();
			dispatched.get(0).run();
			assertFalse(fired.get());
		}
	}

	private static final class CapturingExecutor extends ScheduledThreadPoolExecutor {

		private final List<Pending> tasks = new ArrayList<>();

		private CapturingExecutor() {
			super(1);
		}

		@Override
		public ScheduledFuture<?> schedule(Runnable command, long delay, TimeUnit unit) {
			Pending pending = new Pending(command, unit.toNanos(delay));
			tasks.add(pending);
			return pending;
		}

		private Pending latest() {
			return tasks.get(tasks.size() - 1);
		}
	}

	private static final class Pending extends FutureTask<Void> implements ScheduledFuture<Void> {

		private final long delayNanos;

		private Pending(Runnable action, long delayNanos) {
			super(action, null);
			this.delayNanos = delayNanos;
		}

		@Override
		public long getDelay(TimeUnit unit) {
			return unit.convert(delayNanos, TimeUnit.NANOSECONDS);
		}

		@Override
		public int compareTo(Delayed other) {
			return Long.compare(delayNanos, other.getDelay(TimeUnit.NANOSECONDS));
		}
	}
}
